<?php
declare(strict_types=1);
require_once __DIR__.'/returns-lib.php';require_once __DIR__.'/receipt-files.php';
function receipt_schema(PDO $db): void {
 $db->exec("CREATE TABLE IF NOT EXISTS return_batches(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT UNIQUE NOT NULL,file_name TEXT NOT NULL,file_path TEXT NOT NULL,file_hash TEXT NOT NULL,received_date TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS return_receipts(id INTEGER PRIMARY KEY AUTOINCREMENT,batch_id INTEGER NOT NULL,original_tracking TEXT NOT NULL,tracking TEXT NOT NULL,source_sheet TEXT NOT NULL,source_row INTEGER NOT NULL,manual INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'missing',matches TEXT NOT NULL DEFAULT '[]');
 CREATE INDEX IF NOT EXISTS return_receipts_batch ON return_receipts(batch_id,id);
 CREATE TABLE IF NOT EXISTS return_receipt_marks(sheet_id TEXT NOT NULL,row_key TEXT NOT NULL,entry_id INTEGER NOT NULL,tracking TEXT NOT NULL,col INTEGER NOT NULL,before_cell TEXT NOT NULL,PRIMARY KEY(sheet_id,row_key));");
}
function receipt_batch(PDO $db,int $id): array {
 $q=$db->prepare('SELECT id,file_name,received_date,actor,created_at,revision FROM return_batches WHERE id=?');$q->execute([$id]);$batch=$q->fetch();if(!$batch)throw new RuntimeException('Không tìm thấy file hoàn.',404);$q=$db->prepare('SELECT * FROM return_receipts WHERE batch_id=? ORDER BY id');$q->execute([$id]);$batch['entries']=$q->fetchAll();foreach($batch['entries'] as &$e){$e['matches']=json_decode($e['matches'],true,512,JSON_THROW_ON_ERROR);$e['manual']=(bool)$e['manual'];}unset($e);return $batch;
}
function receipt_batches(PDO $db,string $date=''): array {
 $q=$db->prepare("SELECT b.id,b.file_name,b.received_date,b.actor,b.created_at,b.revision,COUNT(r.id) AS total,SUM(CASE WHEN r.state='matched' THEN 1 ELSE 0 END) AS matched,SUM(CASE WHEN r.state<>'matched' AND r.manual=1 THEN 1 ELSE 0 END) AS manual FROM return_batches b LEFT JOIN return_receipts r ON r.batch_id=b.id".($date!==''?' WHERE b.received_date=?':'').' GROUP BY b.id ORDER BY b.received_date DESC,b.id DESC LIMIT 200');$q->execute($date!==''?[$date]:[]);return $q->fetchAll();
}
function receipt_apply(PDO $db,int $batchId,array $user,?array $change=null,?int $revision=null,bool $external=false): array {
 if(!$external)$db->exec('BEGIN IMMEDIATE');try{
  $batch=receipt_batch($db,$batchId);if($revision!==null&&(int)$batch['revision']!==$revision)throw new RuntimeException('File vừa được người khác cập nhật. Tải lại file rồi sửa tiếp.',409);
  if($change){$entryId=$change['id']??null;$tracking=trim((string)($change['tracking']??''));$note=trim((string)($change['note']??''));if(!is_int($entryId)||strlen($tracking)>40||mb_strlen($note)>1000)throw new RuntimeException('Kiểm tra mã vận đơn và ghi chú.',400);$q=$db->prepare('UPDATE return_receipts SET tracking=?,manual=?,note=? WHERE id=? AND batch_id=?');$q->execute([$tracking,!empty($change['manual'])?1:0,$note,$entryId,$batchId]);if(!$q->rowCount())throw new RuntimeException('Không tìm thấy dòng cần sửa.',404);$batch=receipt_batch($db,$batchId);}
  $current=wb_current($db);if(!$current)throw new RuntimeException('Chưa có bảng đơn.',409);$snapshot=$current['snapshot'];$index=[];$patches=[];
  foreach($snapshot['sheetOrder'] as $sid){$s=$snapshot['sheets'][$sid];[$tc]=returns_columns($s);$hc=null;foreach(($s['cellData'][0]??[]) as $c=>$cell)if(report_fold(returns_text($cell))==='HOAN')$hc=(int)$c;if($tc===null||$hc===null)continue;foreach(($s['cellData']??[]) as $r=>$cells){if((int)$r<1)continue;$code=preg_replace('/\s+/u','',returns_text($cells[$tc]??null));if($code==='')continue;$index[$code][]=['sheet'=>$sid,'row'=>(int)$r,'col'=>$hc,'name'=>$s['name'],'key'=>(string)($cells[0]['custom']['victorRowId']??('row:'.$r))];}}
  foreach($batch['entries'] as $entry){$entryId=(int)$entry['id'];$code=trim($entry['tracking']);$old=$db->prepare('SELECT * FROM return_receipt_marks WHERE entry_id=?');$old->execute([$entryId]);foreach($old as $mark){foreach(($index[$mark['tracking']]??[]) as $loc){if($loc['sheet']!==$mark['sheet_id']||$loc['key']!==$mark['row_key']||$loc['col']!==(int)$mark['col'])continue;$cell=$snapshot['sheets'][$loc['sheet']]['cellData'][$loc['row']][$loc['col']]??null;if(returns_text($cell)!==$mark['tracking'])continue;$cell=json_decode($mark['before_cell'],true);$snapshot['sheets'][$loc['sheet']]['cellData'][$loc['row']][$loc['col']]=$cell;$patches[$loc['sheet'].'|'.$loc['row'].'|'.$loc['col']]=$loc+['cell'=>$cell];}}
   $db->prepare('DELETE FROM return_receipt_marks WHERE entry_id=?')->execute([$entryId]);$matches=[];$locations=preg_match('/^\d{8,20}$/D',$code)?($index[$code]??[]):[];
   foreach($locations as $loc){$sid=$loc['sheet'];$r=$loc['row'];$c=$loc['col'];$before=$snapshot['sheets'][$sid]['cellData'][$r][$c]??null;$cell=$before??[];unset($cell['f'],$cell['si'],$cell['p']);$cell['v']=$code;$cell['t']=1;$snapshot['sheets'][$sid]['cellData'][$r][$c]=$cell;$patches[$sid.'|'.$r.'|'.$c]=$loc+['cell'=>$cell];$db->prepare('INSERT INTO return_receipt_marks VALUES(?,?,?,?,?,?) ON CONFLICT(sheet_id,row_key) DO UPDATE SET entry_id=excluded.entry_id,tracking=excluded.tracking,col=excluded.col,before_cell=excluded.before_cell')->execute([$sid,$loc['key'],$entryId,$code,$c,json_encode($before,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$matches[]=['sheet'=>$loc['name'],'row'=>$r+1];}
   $db->prepare('UPDATE return_receipts SET state=?,matches=? WHERE id=?')->execute([$matches?'matched':'missing',json_encode($matches,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$entryId]);
  }
  foreach($patches as $key=>$patch)if(($current['snapshot']['sheets'][$patch['sheet']]['cellData'][$patch['row']][$patch['col']]??null)===$patch['cell'])unset($patches[$key]);$version=$current['version'];if($patches)$version=wb_store($db,$snapshot,$current['sources'],$version,$user['username'],null,[['command'=>'return_receipts.scan','at'=>(int)(microtime(true)*1000)]],true)['version'];
  $db->prepare('UPDATE return_batches SET revision=revision+1 WHERE id=?')->execute([$batchId]);if(function_exists('people_audit'))people_audit('return_receipts',(string)$batchId,['action'=>$change?'edit':'scan','change'=>$change,'workbookVersion'=>$version,'updatedCells'=>count($patches)],$db);$result=['batch'=>receipt_batch($db,$batchId),'version'=>$version];if(!$external)$db->exec('COMMIT');return $result;
 }catch(Throwable $e){if(!$external)$db->exec('ROLLBACK');throw $e;}
}
function receipt_import(PDO $db,array $entries,array $file,array $user): array {
 $db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT id FROM return_batches WHERE request_key=?');$q->execute([$file['key']]);if($id=$q->fetchColumn()){$result=['batch'=>receipt_batch($db,(int)$id)];$db->exec('COMMIT');return $result;}
  $db->prepare('INSERT INTO return_batches(request_key,file_name,file_path,file_hash,received_date,actor,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$file['key'],$file['name'],$file['path'],$file['hash'],$file['date'],$user['username'],gmdate('c')]);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO return_receipts(batch_id,original_tracking,tracking,source_sheet,source_row) VALUES(?,?,?,?,?)');foreach($entries as $e)$q->execute([$id,$e['original'],$e['tracking'],$e['sheet'],$e['row']]);$result=receipt_apply($db,$id,$user,null,null,true);$db->exec('COMMIT');return $result;
 }catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
